std::vector<unsigned char> YAML_CPP_API::DecodeBase64(const std::string &input) {
    if (input.empty()) {
        return {};
    }

    std::vector<unsigned char> ret(3 * input.size() / 4 + 1);
    unsigned char *out = &ret[0];
    unsigned value = 0;
    int cnt = 0;

    for (std::size_t i = 0; i < input.size(); ++i) {
        if (std::isspace(static_cast<unsigned char>(input[i]))) {
            continue;
        }

        unsigned d = decoding[static_cast<unsigned char>(input[i])];
        if (d == 255) {
            return {};
        }

        value = (value << 6) | d;
        if (++cnt == 3) {
            *out++ = value >> 16;
            if (i > 0 && input[i - 1] != '=') {
                *out++ = value >> 8;
            }
            if (input[i] != '=') {
                *out++ = value;
            }
            cnt = 0;
        }
    }

    if (cnt != 0) {
        return {};
    }

    ret.resize(out - &ret[0]);
    return ret;
}
